from databricks.sdk import WorkspaceClient

w = WorkspaceClient()
print("clusters:")
try:
    for c in w.clusters.list():
        print(" ", c.cluster_id, c.cluster_name, c.state, c.cluster_source)
except Exception as e:
    print("  err:", e)

print("can create cluster?")
try:
    spec = w.clusters.create(cluster_name="mlpab2efe57_probe", spark_version="15.4.x-scala2.12",
                             num_workers=0, node_type_id="i3.xlarge",
                             autotermination_minutes=10)
    print("  created", spec)
except Exception as e:
    print("  err:", type(e).__name__, e)

print("existing jobs:")
try:
    for j in w.jobs.list(limit=5):
        print(" ", j.job_id, j.settings.name if j.settings else None)
except Exception as e:
    print("  err:", e)

